<script setup lang="ts">
import GameWindow from '../components/GameWindow.vue';
import {state,back,errorText} from '../services/game-store';
import {setAnalyticsConsent} from '../services/analytics';
const t=(ru:string,en:string)=>state.locale==='ru'?ru:en;
function choose(enabled:boolean){try{setAnalyticsConsent(enabled);back();}catch(e){state.error=errorText(e);}}
</script>
<template><GameWindow :title="t('Поможем игре стать лучше?','Help make the game better?')"><img class="analytics-question-art" src="/assets/branding/ui/hud-player-portrait-v1.png" alt=""><p>{{t('Разрешите обезличенную аналитику интерфейса, чтобы находить неудобные окна и улучшать Untouch.','Allow interface analytics to help identify confusing screens and improve Untouch.')}}</p><p class="hint">{{t('Это добровольно. Игра, энергия и награды доступны при любом выборе. Разрешение можно отозвать в аккаунте.','This is optional. Gameplay, energy and rewards remain available with either choice. You can revoke permission in your account.')}}</p><details><summary>{{t('Какие данные отправляются','What is sent')}}</summary><p>{{t('Названия открытых окон и нажатых кнопок из ограниченного списка, без игровых результатов, содержимого полей, текстов, кодов приглашений и дополнительных свойств событий. Сервис: Яндекс Метрика; запись экрана и карта кликов выключены.','Screen and button names from a limited list, without run results, field contents, message text, invitation codes or custom event properties. Provider: Yandex Metrika; session recording and click maps are disabled.')}}</p></details><template #footer><button class="primary full" @click="choose(true)">{{t('Разрешить аналитику','Allow analytics')}}</button><button class="text-button full" @click="choose(false)">{{t('Нет, спасибо','No, thanks')}}</button></template></GameWindow></template>
<style scoped>.analytics-question-art{display:block;width:86px;height:86px;object-fit:contain;margin:4px auto 12px}p{line-height:1.45}details{margin:12px 0}</style>
